class MoveOnly {
public:
  // User-declared move constructor.
  MoveOnly(MoveOnly&& other) noexcept = default;

  // Because a move operation is declared, the compiler implicitly
  // DELETES the copy constructor and copy assignment operator.
  // MoveOnly m1;
  // MoveOnly m2 = m1; // Error! Copy constructor is deleted.
};

class CopyAndMove {
public:
  CopyAndMove(CopyAndMove&& other) noexcept = default;
  CopyAndMove(const CopyAndMove& other) = default; // Re-enable copy
  // This class is now both copyable and movable.
};
